        }
      ],
      "rule": "weight + 0.85*residual_pack + 0.15*residual_cover - 0.25*neighbor_pack + 0.08*neighbor_edges/max(1e-9,abs(1+degree)) + 0.01*residual_mass/max(1e-9,abs(1+remaining_count)) + 0.03*residual_peak/max(1e-9,abs(1+weight)) - 0.01*degree",
      "rationale": "The shown seed repairs matched degree rewards. Emphasize feasible residual packing while retaining modest cover guidance and removing boundary and residual-edge scans."
    },
    {
      "name": "exchange_surplus",
      "features": [
        {
          "name": "neighbor_pack",
          "expression": {"op":"greedy_independent_weight","args":[{"op":"neighbors","args":[{"op":"root","args":[]}]}]}
