        }
      ],
      "rule": "(weight-0.7*neighbor_pack)/max(1e-9,abs(1+neighbor_mass)) + 0.3*residual_pack + 0.15*max(0,neighbor_cover-neighbor_pack)/max(1e-9,abs(1+degree)) + 0.1*neighbor_edges/max(1e-9,abs(1+degree)) - 0.02*neighbor_mass/max(1e-9,abs(1+remaining_count)) + 0.05*residual_peak/max(1e-9,abs(1+weight))",
      "rationale": "Price inclusion against a feasible neighborhood alternative. Test whether neighborhood cover slack and internal conflicts identify redundant competitors worth displacing."
    },
    {
