        {
          "name": "neighbor_mass",
          "expression": {"op":"sum_weights","args":[{"op":"neighbors","args":[{"op":"root","args":[]}]}]}
        },
        {
          "name": "neighbor_count",
          "expression": {"op":"count","args":[{"op":"neighbors","args":[{"op":"root","args":[]}]}]}
        },
        {
          "name": "residual_mass",
          "expression": {"op":"sum_weights","args":[{"op":"difference","args":[{"op":"difference","args":[{"op":"available","args":[]},{"op":"neighbors","args":[{"op":"root","args":[]}]}]},{"op":"singleton","args":[{"op":"root","args":[]}]}]}]}
