        },
        {
          "name": "residual_peak",
          "expression": {"op":"max_weight","args":[{"op":"difference","args":[{"op":"difference","args":[{"op":"available","args":[]},{"op":"neighbors","args":[{"op":"root","args":[]}]}]},{"op":"singleton","args":[{"op":"root","args":[]}]}]}]}
        },
        {
          "name": "neighbor_pack",
