        },
        {
          "name": "neighbor_edges",
          "expression": {"op":"count","args":[{"op":"induced_edges","args":[{"op":"neighbors","args":[{"op":"root","args":[]}]}]}]}
        }
      ],
      "rule": "weight + max(residual_peak,residual_mass-residual_edge_min) - 0.25*neighbor_pack - 0.03*residual_edge_product/max(1e-9,abs(1+residual_mass)) + 0.05*neighbor_edges/max(1e-9,abs(1+degree)) - 0.01*degree",
      "rationale": "Replace residual packing and cover with a conservative edge-minimum reward certificate. Use neighborhood packing to price feasible exchanges and weighted residual edges to break ties."
    },
    {
      "name": "density_ambiguity_switch",
      "features": [
        {
          "name": "residual_pack",
          "expression": {"op":"greedy_independent_weight","args":[{"op":"difference","args":[{"op":"difference","args":[{"op":"available","args":[]},{"op":"neighbors","args":[{"op":"root","args":[]}]}]},{"op":"singleton","args":[{"op":"root","args":[]}]}]}]}
