        },
        {
          "name": "neighbor_count",
          "expression": {"op":"count","args":[{"op":"neighbors","args":[{"op":"root","args":[]}]}]}
        }
      ],
      "rule": "weight + (residual_pack if 2*degree <= remaining_count else 0.65*residual_pack+0.35*residual_cover) - 0.2*neighbor_pack - 0.1*max(0,neighbor_cover-neighbor_pack) - 0.05*max(0,residual_cover-residual_pack)/max(1e-9,abs(1+remaining_count)) + 0.05*residual_count/max(1e-9,abs(1+remaining_count)) - 0.02*neighbor_count",
      "rationale": "Test a density-dependent blend of residual feasible packing and cover. Penalize primal-dual ambiguity in both retained and displaced sets."
    },
    {
      "name": "deletion_primal_regret",
