        }
      ],
      "rule": "weight + residual_pack - 0.6*max(0,deleted_pack-residual_pack) + 0.15*max(0,available_pack-deleted_pack) - 0.1*neighbor_pack + 0.05*neighbor_edges/max(1e-9,abs(1+degree)) + 0.01*residual_mass/max(1e-9,abs(1+remaining_count))",
      "rationale": "Compare retained, deletion-only and full-set feasible packings to estimate inclusion regret and root sensitivity. Accept extra packing work as a distinct quality hypothesis."
    },
    {
      "name": "boundary_primal",
      "features": [
        {
          "name": "neighbor_edges",
