        },
        {
          "name": "deleted_edges",
          "expression": {"op":"count","args":[{"op":"induced_edges","args":[{"op":"difference","args":[{"op":"available","args":[]},{"op":"singleton","args":[{"op":"root","args":[]}]}]}]}]}
        },
        {
          "name": "neighbor_count",
          "expression": {"op":"count","args":[{"op":"neighbors","args":[{"op":"root","args":[]}]}]}
        },
        {
          "name": "residual_count",
          "expression": {"op":"count","args":[{"op":"difference","args":[{"op":"difference","args":[{"op":"available","args":[]},{"op":"neighbors","args":[{"op":"root","args":[]}]}]},{"op":"singleton","args":[{"op":"root","args":[]}]}]}]}
        },
