          "name": "residual_pack",
          "expression": {"op":"greedy_independent_weight","args":[{"op":"difference","args":[{"op":"difference","args":[{"op":"available","args":[]},{"op":"neighbors","args":[{"op":"root","args":[]}]}]},{"op":"singleton","args":[{"op":"root","args":[]}]}]}]}
        }
      ],
      "rule": "weight + 0.9*residual_pack + 0.15*(deleted_edges-neighbor_edges-residual_edges)/max(1e-9,abs(1+neighbor_count)) + 0.1*neighbor_edges/max(1e-9,abs(1+neighbor_count)) - 0.08*residual_edges/max(1e-9,abs(1+residual_count)) - 0.02*neighbor_count",
      "rationale": "Keep feasible residual packing and the seed's boundary-exposure mechanism. Replace cover and neighborhood packing with edge and cardinality statistics to test lower feature work."
    },
    {
      "name": "deletion_dual_regret",
      "features": [
        {
          "name": "residual_cover",
          "expression": {"op":"clique_cover_weight","args":[{"op":"difference","args":[{"op":"difference","args":[{"op":"available","args":[]},{"op":"neighbors","args":[{"op":"root","args":[]}]}]},{"op":"singleton","args":[{"op":"root","args":[]}]}]}]}
